// Microsoft Postfach, persoenlich je Person. Lesen und Entwuerfe, kein Senden:
// die Anwendung fordert Mail.Send gar nicht erst an, ein Sendeversuch scheitert
// deshalb bei Microsoft und nicht erst an einer Selbstbeschraenkung hier.

const input = { ...$input.first().json };
for (const _k of Object.keys(input)) { if (input[_k] === '' || input[_k] === null) delete input[_k]; }
const action = input.action || '';
const caller = String(input.caller || '').trim();

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
const GRAPH = 'https://graph.microsoft.com/v1.0';
function fail(m) { return [{ json: { error: m } }]; }

const credRows = await helpers.httpRequest({
  method: 'GET', url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true });
const cred = {}; for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
for (const need of ['tenant_id','client_id','client_secret','token_key','redirect_uri'])
  if (!cred[need]) return fail('Microsoft ist nicht eingerichtet, es fehlt: ' + need);
const connectUrl = String(cred.redirect_uri).replace('ms-oauth-callback', 'ms-connect');

if (!caller) return fail('Kein Nutzerbezug vorhanden. Postfachzugriff geht nur im Namen einer angemeldeten Person.');

let personKey = caller;
if (!caller.startsWith('entra:')) {
  try {
    const map = await helpers.httpRequest({ method: 'GET',
      url: SUPABASE_URL + '/rest/v1/user_identity_map?legacy_key=eq.' + encodeURIComponent(caller) + '&select=entra_key',
      headers: pg, json: true });
    if (map && map[0] && map[0].entra_key) personKey = map[0].entra_key;
  } catch (e) {}
}

async function accessToken() {
  const rows = await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/get_user_token',
    headers: pg, json: true,
    body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key }) });
  const row = rows && rows[0];
  if (!row) return { error: 'Fuer diese Person ist noch kein Microsoft-Konto verbunden. Einmalig verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  if (row.status !== 'connected') return { error: 'Die Verbindung ist unterbrochen (' + row.status + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  if (new Date(row.expires_at).getTime() - Date.now() > 5 * 60 * 1000) return { token: row.access_token };
  if (!row.refresh_token) return { error: 'Der Zugang ist abgelaufen. Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  let tok;
  try {
    tok = await helpers.httpRequest({ method: 'POST',
      url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true,
      body: 'client_id=' + encodeURIComponent(cred.client_id) + '&client_secret=' + encodeURIComponent(cred.client_secret) +
            '&refresh_token=' + encodeURIComponent(row.refresh_token) + '&grant_type=refresh_token&scope=' + encodeURIComponent(row.scopes || '') });
  } catch (e) {
    const b = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : String(e.message || e);
    const code = (b.match(/AADSTS\d+/) || ['unbekannt'])[0];
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: code }) });
    return { error: 'Die Verbindung ist beendet (' + code + '). Bitte neu verbinden: ' + connectUrl + '?user=' + encodeURIComponent(caller) };
  }
  await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token', headers: pg,
    body: JSON.stringify({ p_user_key: personKey, p_provider: 'microsoft', p_key: cred.token_key,
      p_access_token: tok.access_token, p_refresh_token: tok.refresh_token || '',
      p_expires_at: new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString(),
      p_scopes: tok.scope || row.scopes || null, p_account_id: row.account_id || '' }) });
  return { token: tok.access_token };
}

const t = await accessToken();
if (t.error) return fail(t.error);
const H = { Authorization: 'Bearer ' + t.token, 'Content-Type': 'application/json' };

function errText(e) {
  const b = e && e.response && e.response.body;
  if (b && b.error && b.error.message) return b.error.message;
  return String((e && e.message) || e);
}
// Status aus allem, was ein n8n-Fehler tragen kann: httpCode (String), statusCode,
// response.statusCode/status, zuletzt die Meldung "Request failed with status code 403".
function httpStatus(e) {
  const r = (e && e.response) || (e && e.cause && e.cause.response) || {};
  const st = Number((e && (e.httpCode || e.statusCode)) || r.statusCode || r.status || 0) || 0;
  if (st) return st;
  const m = String((e && (e.message || e.description)) || '').match(/status code (\d{3})/i);
  return m ? Number(m[1]) : 0;
}
function graphCode(e) {
  const b = (e && e.response && e.response.body) || (e && e.cause && e.cause.response && e.cause.response.body) || {};
  return String((b && b.error && b.error.code) || (e && e.description) || '');
}
// Fremdes Postfach (10.09.2026): freigegebene oder angehaengte Postfaecher, etwa
// Vertretungen (Michael, 07.09.). Basis ist dann /users/{adresse} statt /me; die
// Berechtigung Mail.Read.Shared wirkt nur dort, wo die Person das Postfach in
// Outlook auch wirklich sieht. Sonst antwortet Microsoft mit 403, und das
// heisst genau das: nicht freigegeben, nicht "gibt es nicht".
const mailbox = String(input.mailbox || input.shared_mailbox || '').trim().toLowerCase();
if (mailbox && !mailbox.includes('@')) return fail('Parameter "mailbox" muss eine E-Mail-Adresse sein (das freigegebene Postfach), z. B. info@salzburgerland.com.');
const BASIS = mailbox ? (GRAPH + '/users/' + encodeURIComponent(mailbox)) : (GRAPH + '/me');
const WO = mailbox ? ' im Postfach ' + mailbox : '';
function fremdesPostfachFehler(e, was) {
  if (!mailbox) return null;
  const st = httpStatus(e); const code = graphCode(e);
  if (st === 403 || st === 401 || /ErrorAccessDenied|Authorization_RequestDenied/i.test(code)) return 'Das Postfach ' + mailbox + ' ist fuer diese Person nicht freigegeben (Microsoft lehnt den Zugriff ab). Freigeben kann es die Besitzerin in Outlook oder die IT; bis dahin kann die Person selbst dort nachsehen.';
  if (st === 404 || /NotFound|ErrorInvalidUser|MailboxNotEnabled/i.test(code)) {
    if (was === 'nachricht' && /ErrorItemNotFound/i.test(code)) return 'Die Nachricht wurde im Postfach ' + mailbox + ' nicht gefunden. Bitte zuerst mit search_messages und derselben mailbox suchen.';
    if (was === 'nachricht' && !code) return 'Nachricht oder Postfach ' + mailbox + ' nicht gefunden. Bitte zuerst mit search_messages und derselben mailbox suchen.';
    // Ohne Freigabe antwortet Microsoft ebenfalls mit 404 (gemessen 10.09.2026 mit dem Pilotkonto
    // auf ein bestehendes Postfach): beide Moeglichkeiten nennen, nicht 'gibt es nicht'.
    return 'Das Postfach ' + mailbox + ' ist fuer diese Person nicht erreichbar: entweder ist es nicht freigegeben (Microsoft meldet dann "nicht gefunden") oder die Adresse stimmt nicht. Freigeben kann es die Besitzerin in Outlook oder die IT; bis dahin kann die Person selbst dort nachsehen.';
  }
  return null;
}
function kurz(s, n) { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '...' : s; }
// --- Entwuerfe wie normale Outlook-Mails (Florian Schumacher, 14.09.2026) ---
// Vorher ging der Text als contentType "text" an Graph. Outlook zeigt das in
// einer Schreibmaschinenschrift ohne Absaetze, und eine Signatur gab es nie.
function htmlText(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function htmlAbsaetze(text) {
  const zeilen = String(text || '').split(/\r?\n/);
  let out = '';
  let liste = false;
  for (const z of zeilen) {
    const m = z.match(/^\s*[-*\u2022]\s+(.*)$/);
    if (m) {
      if (!liste) { out += '<ul>'; liste = true; }
      out += '<li>' + htmlText(m[1]) + '</li>';
      continue;
    }
    if (liste) { out += '</ul>'; liste = false; }
    out += z.trim() === '' ? '<div><br></div>' : '<div>' + htmlText(z) + '</div>';
  }
  if (liste) out += '</ul>';
  return '<div style="font-family:Calibri,Arial,sans-serif;font-size:11pt">' + out + '</div>';
}
// Signatur aus den zuletzt gesendeten Mails der Person. Outlook im Web und das
// neue Outlook markieren sie mit id="Signature". Sonst wird der Block nach der
// letzten Grussformel genommen, aber nur wenn er kurz ist und kein Zitat
// enthaelt. Findet sich nichts, wird ohne Signatur angelegt und das gesagt.
// Grussformeln IMMER mit Wortgrenze. Ohne sie traf "lg" mitten in Woertern
// ("Erfolg", "Vorlage"), und ab dieser Stelle wurde der halbe Mailtext als
// Signatur in einen neuen Entwurf getragen.
const _GRUSS_SIG_RE = /\b(?:(?:mit\s+freundlichen|liebe|liebste|beste|viele|herzliche|sonnige)\s+gr[uü]e?[sß]+en?|best\s+regards|kind\s+regards|lg|vg|mfg)\b/gi;
const _ZITAT_RE = /(<blockquote|<hr|id=["']?divRplyFwdMsg|id=["']?appendonsend|Von:\s|From:\s|Gesendet:\s|Sent:\s)/i;
// Ein Signaturblock kann verschachtelte divs enthalten. Das nicht-gierige Muster
// schnitt am ersten </div> ab und liess ein offenes div zurueck.
function divBlock(h, start) {
  let i = start, tiefe = 0;
  const re = /<(\/?)div\b[^>]*>/gi;
  re.lastIndex = start;
  let m;
  while ((m = re.exec(h)) !== null) {
    tiefe += m[1] ? -1 : 1;
    i = m.index + m[0].length;
    if (tiefe === 0) return h.slice(start, i);
    if (i - start > 6000) break;
  }
  return null;
}
// Was aus einer fremden Mail nicht in einen neuen Entwurf gehoert: Bilder, die
// als Anhang der alten Mail lagen, und Rumpfabschluesse mitten im Text.
function signaturSaeubern(s) {
  return String(s)
    .replace(/<img[^>]*src=["']?cid:[^>]*>/gi, '')
    .replace(/<\/?(?:body|html)[^>]*>/gi, '')
    .trim();
}
function signaturAus(html) {
  const h = String(html || '');
  if (!h) return null;
  const marke = h.search(/<div[^>]*id=["']?Signature["']?[^>]*>/i);
  if (marke >= 0) {
    const block = divBlock(h, marke);
    if (block) {
      const sauber = signaturSaeubern(block);
      if (sauber.replace(/<[^>]+>/g, ' ').trim().length >= 3) return sauber;
    }
  }
  let letzte = -1;
  let m;
  _GRUSS_SIG_RE.lastIndex = 0;
  while ((m = _GRUSS_SIG_RE.exec(h)) !== null) letzte = m.index;
  if (letzte < 0) return null;
  const rest = h.slice(letzte);
  if (rest.length > 900 || _ZITAT_RE.test(rest)) return null;
  const sauber = signaturSaeubern(rest);
  const nurText = sauber.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').trim();
  // Eine Signatur ist kurz und enthaelt keinen Fliesstext mehr.
  if (nurText.length < 10 || nurText.length > 400) return null;
  return '<div>' + sauber + '</div>';
}
async function signaturHolen() {
  try {
    const r = await helpers.httpRequest({ method: 'GET',
      url: GRAPH + '/me/mailFolders/sentitems/messages?$top=5&$select=body',
      headers: H, json: true, timeout: 15000 });
    for (const m of ((r && r.value) || [])) {
      const s = signaturAus((m.body || {}).content);
      if (s) return s;
    }
  } catch (_e) {}
  return null;
}
// Den eigenen Text VOR das Zitat setzen, statt den ganzen Rumpf zu ersetzen.
// Bisher verschwand mit dem PATCH die zitierte Nachricht aus dem Entwurf.
function vorDasZitat(vorhanden, neuHtml) {
  const h = String(vorhanden || '');
  if (!h.trim()) return neuHtml;
  for (const re of [/<div[^>]*id=["']?appendonsend["']?[^>]*>/i, /<div[^>]*id=["']?divRplyFwdMsg["']?[^>]*>/i]) {
    const m = h.match(re);
    if (m && m.index !== undefined) return h.slice(0, m.index) + neuHtml + h.slice(m.index);
  }
  // <hr> nur als Rueckfall, und nur im vorderen Teil: ein Trennstrich kann auch
  // INNERHALB der zitierten Nachricht stehen, dann laege die eigene Antwort
  // mitten im Zitat.
  const hr = h.match(/<hr[^>]*>/i);
  if (hr && hr.index !== undefined && hr.index < Math.min(3000, h.length / 2)) {
    return h.slice(0, hr.index) + neuHtml + h.slice(hr.index);
  }
  const b = h.match(/<body[^>]*>/i);
  if (b && b.index !== undefined) return h.slice(0, b.index + b[0].length) + neuHtml + h.slice(b.index + b[0].length);
  return neuHtml + h;
}
// Ordnername auf eine Ordner-Id aufloesen (Lea Steurer, 15.09.2026: ihr
// ToDo-Ordner). Erst die bekannten Namen, dann die oberste Ebene, dann die
// Unterordner des Posteingangs. Mehr wird nicht durchsucht, damit ein Aufruf
// nicht zu zwei Dutzend Abfragen wird.
const _WELLKNOWN = { posteingang: 'inbox', inbox: 'inbox', gesendet: 'sentitems', 'gesendete elemente': 'sentitems',
  'sent items': 'sentitems', entwuerfe: 'drafts', 'entw\u00fcrfe': 'drafts', drafts: 'drafts',
  'geloeschte elemente': 'deleteditems', 'gel\u00f6schte elemente': 'deleteditems', papierkorb: 'deleteditems', archiv: 'archive', archive: 'archive' };
async function ordnerId(name) {
  const suche = String(name || '').trim();
  if (!suche) return { id: null };
  const wk = _WELLKNOWN[suche.toLowerCase()];
  if (wk) return { id: wk };
  const gleich = (liste) => (liste || []).filter(f => String(f.displayName || '').toLowerCase() === suche.toLowerCase());
  let oben;
  try {
    oben = await helpers.httpRequest({ method: 'GET', url: BASIS + '/mailFolders?$top=60&$select=id,displayName', headers: H, json: true });
  } catch (e) {
    // Bei einem fremden Postfach ist die Ursache fast immer die fehlende Freigabe.
    const f = fremdesPostfachFehler(e);
    if (f) return { fehler: f };
    throw e;
  }
  let treffer = gleich((oben || {}).value);
  if (!treffer.length) {
    try {
      const unten = await helpers.httpRequest({ method: 'GET', url: BASIS + '/mailFolders/inbox/childFolders?$top=60&$select=id,displayName', headers: H, json: true });
      treffer = gleich((unten || {}).value);
    } catch (e) { /* ohne Unterordner weiter, die Meldung unten nennt die oberste Ebene */ }
  }
  if (treffer.length === 1) return { id: treffer[0].id, name: treffer[0].displayName };
  const namen = (((oben || {}).value) || []).map(f => f.displayName).filter(Boolean).slice(0, 25);
  if (treffer.length > 1) {
    return { fehler: 'Mehrere Ordner heissen "' + suche + '"' + WO + '. Bitte genauer benennen.' };
  }
  return { fehler: 'Einen Ordner "' + suche + '" finde ich nicht' + WO + '. Vorhanden sind unter anderem: ' + namen.join(', ') + '.' };
}
function zeile(m) {
  const von = ((m.from || {}).emailAddress || {}).name || ((m.from || {}).emailAddress || {}).address || '?';
  return '- ' + String(m.receivedDateTime || '').replace('T', ' ').slice(0, 16) + '  von ' + von +
         (m.isRead === false ? '  [ungelesen]' : '') + '\n  ' + kurz(m.subject, 90) +
         '\n  ' + kurz(m.bodyPreview, 140) + '\n  (id: ' + m.id + ')';
}

try {
  if (action === 'search_messages') {
    const limit = Math.min(parseInt(input.limit || '10', 10) || 10, 25);
    let basis = BASIS;
    let ordnerText = '';
    if (input.folder) {
      const o = await ordnerId(input.folder);
      if (o.fehler) return fail(o.fehler);
      if (o.id) { basis = BASIS + '/mailFolders/' + encodeURIComponent(o.id); ordnerText = ' im Ordner ' + (o.name || input.folder); }
    }
    let url = basis + '/messages?$top=' + limit + '&$select=id,subject,from,receivedDateTime,bodyPreview,isRead';
    if (input.query) url += '&$search=' + encodeURIComponent('"' + String(input.query).replace(/"/g, '') + '"');
    else url += '&$orderby=receivedDateTime desc';
    if (String(input.unread_only || '').toLowerCase() === 'true') url += (input.query ? '' : '&$filter=isRead eq false');
    let r;
    try { r = await helpers.httpRequest({ method: 'GET', url, headers: Object.assign({ ConsistencyLevel: 'eventual' }, H), json: true }); }
    catch (e) { const f = fremdesPostfachFehler(e); if (f) return fail(f); throw e; }
    const ms = (r && r.value) || [];
    if (!ms.length) return [{ json: { result: 'Keine passenden Nachrichten gefunden' + WO + ordnerText + '.' } }];
    return [{ json: { result: ms.length + ' Nachrichten' + WO + ordnerText + ':\n' + ms.map(zeile).join('\n') } }];
  }

  if (action === 'get_message') {
    if (!input.message_id) return fail('Parameter "message_id" ist noetig, die id steht bei jeder Nachricht aus search_messages.');
    let m;
    try {
      m = await helpers.httpRequest({ method: 'GET',
        url: BASIS + '/messages/' + encodeURIComponent(input.message_id) + '?$select=subject,from,toRecipients,receivedDateTime,body',
        headers: H, json: true });
    } catch (e) { const f = fremdesPostfachFehler(e, 'nachricht'); if (f) return fail(f); throw e; }
    const txt = String((m.body || {}).content || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
    return [{ json: { result: 'Von: ' + (((m.from || {}).emailAddress || {}).address || '?') +
      '\nAn: ' + ((m.toRecipients || []).map(x => (x.emailAddress || {}).address).join(', ') || '?') +
      '\nDatum: ' + String(m.receivedDateTime || '').replace('T', ' ').slice(0, 16) +
      '\nBetreff: ' + (m.subject || '') + '\n\n' + kurz(txt, 4000) } }];
  }

  if (action === 'create_draft') {
    if (mailbox) return fail('Entwuerfe kann ich nur im eigenen Postfach anlegen, nicht in ' + mailbox + ' (dafuer fehlt die Schreibberechtigung). Ich lege den Entwurf gern in deinem Postfach an, ohne mailbox.');
    if (!input.subject || !input.body) return fail('Fuer einen Entwurf brauche ich "subject" und "body".');
    const an = String(input.to || '').split(/[,;\s]+/).filter(x => x.includes('@'));
    const sig = await signaturHolen();
    const d = { subject: input.subject, body: { contentType: 'html', content: htmlAbsaetze(input.body) + (sig ? '<div><br></div>' + sig : '') } };
    if (an.length) d.toRecipients = an.map(a => ({ emailAddress: { address: a } }));
    const r = await helpers.httpRequest({ method: 'POST', url: GRAPH + '/me/messages', headers: H, json: true, body: JSON.stringify(d) });
    return [{ json: { result: 'Entwurf liegt im Postfach: "' + r.subject + '"' + (an.length ? ' an ' + an.join(', ') : ' ohne Empfaenger') +
      (sig ? ' Die Signatur aus den zuletzt gesendeten Mails ist angehaengt.' : ' Eine Signatur habe ich in den zuletzt gesendeten Mails nicht gefunden, der Entwurf ist ohne.') +
      ' Er wird NICHT verschickt, das muss die Person selbst tun. (id: ' + r.id + ')' } }];
  }

  if (action === 'reply_draft') {
    if (mailbox) return fail('Antwort-Entwuerfe kann ich nur fuer Nachrichten im eigenen Postfach anlegen, nicht in ' + mailbox + '. Ich kann den Inhalt als neuen Entwurf in deinem Postfach anlegen (create_draft).');
    if (!input.message_id || !input.body) return fail('Fuer eine Antwort brauche ich "message_id" und "body".');
    const r = await helpers.httpRequest({ method: 'POST',
      url: GRAPH + '/me/messages/' + encodeURIComponent(input.message_id) + '/createReply', headers: H, json: true, body: '{}' });
    const sig = await signaturHolen();
    const eigen = htmlAbsaetze(input.body) + (sig ? '<div><br></div>' + sig : '');
    // Der Entwurf aus createReply enthaelt bereits die zitierte Nachricht. Bisher
    // hat der PATCH den ganzen Rumpf ersetzt und das Zitat geloescht.
    const inhalt = vorDasZitat(((r || {}).body || {}).content, eigen);
    await helpers.httpRequest({ method: 'PATCH', url: GRAPH + '/me/messages/' + encodeURIComponent(r.id),
      headers: H, json: true, body: JSON.stringify({ body: { contentType: 'html', content: inhalt } }) });
    return [{ json: { result: 'Antwortentwurf liegt im Postfach, die zitierte Nachricht steht darunter' +
      (sig ? ', die Signatur aus den zuletzt gesendeten Mails ist angehaengt' : ' (ohne Signatur, in den zuletzt gesendeten Mails war keine zu finden)') +
      '. Er wartet auf das Absenden durch die Person. (id: ' + r.id + ')' } }];
  }

  // Lea Steurer, 15.09.2026: angelegte Entwuerfe liessen sich nur in Outlook
  // loeschen. Geloescht wird ausschliesslich, was wirklich ein Entwurf ist und
  // im eigenen Postfach liegt; alles andere wird abgewiesen, nicht geraten.
  if (action === 'delete_draft') {
    if (mailbox) return fail('Loeschen kann ich nur im eigenen Postfach, nicht in ' + mailbox + '.');
    if (!input.message_id) return fail('Zum Loeschen brauche ich "message_id", die id steht in der Antwort von create_draft oder reply_draft.');
    let m;
    try {
      m = await helpers.httpRequest({ method: 'GET',
        url: GRAPH + '/me/messages/' + encodeURIComponent(input.message_id) + '?$select=id,subject,isDraft',
        headers: H, json: true });
    } catch (e) {
      if (httpStatus(e) === 404) return fail('Diese Nachricht gibt es im Postfach nicht (mehr). Vielleicht wurde der Entwurf schon in Outlook geloescht.');
      throw e;
    }
    if (m.isDraft !== true) return fail('Das ist kein Entwurf, sondern eine echte Nachricht ("' + (m.subject || 'ohne Betreff') + '"). Die loesche ich nicht.');
    // Zweistufig wie beim Teams-Boten: ein Entwurf kann auch von der Person selbst
    // stammen und halb fertig sein. Geloescht wird erst nach einem ausdruecklichen Ja.
    const ja = String(input.confirm || '').trim().toLowerCase();
    if (ja !== 'true' && ja !== 'ja' && ja !== 'yes') {
      return [{ json: { result: 'Zum Loeschen vorgemerkt: der Entwurf "' + (m.subject || 'ohne Betreff') + '". '
        + 'Frag die Person, ob der wirklich weg soll, und rufe dann denselben Aufruf mit confirm=true noch einmal auf. '
        + 'Es wurde noch nichts geloescht.' } }];
    }
    await helpers.httpRequest({ method: 'DELETE', url: GRAPH + '/me/messages/' + encodeURIComponent(input.message_id), headers: H, json: false });
    return [{ json: { result: 'Der Entwurf "' + (m.subject || 'ohne Betreff') + '" ist geloescht.' } }];
  }

  return fail('Unbekannte Aktion "' + action + '". Moeglich: search_messages, get_message, create_draft, reply_draft, delete_draft.');
} catch (e) {
  return fail('Microsoft Postfach (' + action + '): ' + errText(e));
}
